export default class BBox{constructor(t=1/0,i=1/0,h=-1/0,s=-1/0){this.minX=t,this.minY=i,this.maxX=h,this.maxY=s}get width(){return this.maxX-this.minX}get height(){return this.maxY-this.minY}addPoint(t,i){Math.abs(t)!==1/0&&(t<this.minX&&(this.minX=t),t>this.maxX&&(this.maxX=t)),Math.abs(i)!==1/0&&(i<this.minY&&(this.minY=i),i>this.maxY&&(this.maxY=i))}copy(){return new BBox(this.minX,this.minY,this.maxX,this.maxY)}}